{\n  position: absolute;\n  bottom: 180px;\n  right: 5px;\n  font-family: 'IBM Plex Mono';\n  font-weight: 100;\n  font-style: italic;\n  color: var(--color-green);\n}\n\n.frequency {\n  position: absolute;\n  bottom: 80px;\n  right: 5px;\n  font-family: 'IBM Plex Mono';\n  font-weight: 100;\n  font-style: italic;\n  color: var(--color-red);\n}\n\n.runtime {\n  position: absolute;\n  bottom: 180px;\n  left: 5px;\n  font-family: 'IBM Plex Mono';\n  font-weight: 100;\n  font-style: italic;\n  color: var(--color-green);\n}\n\n\n.powerlock{\n  display: none;\n  position: absolute;\n  bottom: 15px;\n  left: 5px;\n  // color: #587B7F;\n  color: #DA8F4A;\n  // color: var(--color-yellow-dark);\n}\n\n.quality {\n  position: absolute;\n  bottom: 80px;\n  left: 5px;\n  // font-family: 'IBM Plex Mono';\n  // font-weight: 100;\n  // font-style: italic;\n  color: var(--color-purple);\n}\n\n.diversity {\n  position: absolute;\n  display: table;\n  table-layout: fixed;\n  left: 0px;\n  bottom:0px;\n\n  height: 25px;\n  width: 100%;\n}\n\n.diversity-bar {\n  display: table-cell;\n  height:inherit;\n  border-style: solid;\n  border-width: 1px;\n  border-color: var(--color-gray);\n  box-sizing:border-box;\n}\n\n\n.diversity-bar-blue{\n  background-color: var(--color-blue);\n}\n\n.diversity-bar-red{\n  background-color: var(--color-red);\n}\n\n.diversity-bar-off{\n  background-color: var(--color-black);\n}\n\n\n.errorzone {\n  font-family: IBM Plex Mono;\n  font-weight: 100;\n  font-style: italic;\n  color: var(--color-yellow);\n}\n\n.editzone {\n  position: absolute;\n  font-family: IBM Plex Mono;\n  font-weight: 100;\n  font-style: italic;\n  color: var(--color-yellow);\n  bottom: 10px;\n  display: none;\n}\n\n.editzone .input-group span{\n  background-color: var(--color-black);\n  color: var(--color-white);\n  border-color: var(--color-black);\n}\n\n.editzone input {\n  background-color: var(--color-black);\n  color: var(--color-yellow);\n  border-color: var(--color-gray);\n  text-align: right;\n}\n\n.editzone input:focus {\n  border-color: var(--color-gray);\n  background-color: var(--color-black);\n  color: var(--color-yellow);\n}\n\n.editzone .ext-id {\n  text-align: left;\n}\n\n.editzone .ext-name {\n  text-align: right;\n}\n\n.editzone p.rx-name {\n  padding-left: 5px;\n  color: var(--color-white);\n  font-weight: 300;\n}\n\n.editzone .row {\n  margin-left: 5px;\n  margin-right: 5px;\n}\n\n#save-box {\n  // height: 130px;\n  width: 100%;\n  // position: absolute;\n  // bottom: 15px;\n  display: block;\n}\n\n#save-box .row,\n#paste-box .row {\n  padding-top: 15px;\n}\n\n#paste-box {\n  display: none;\n}\n\n#bulkbox {\n  background-color: var(--color-black);\n  color: var(--color-yellow);\n  border-color: var(--color-gray);\n}\n\n#pco-log-entries {\n  max-height: 240px;\n  overflow-y: auto;\n  font-family: 'IBM Plex Mono', monospace;\n}\n\n#pco-log-entries .pco-log-entry + .pco-log-entry {\n  margin-top: 0.25rem;\n}\n\n/* Numbered steps through the PCO setup: connect, plan, teams, matching. */\n.pco-step-heading {\n  font-family: 'IBM Plex Sans';\n  font-weight: 600;\n  font-size: 1rem;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n  color: var(--color-yellow);\n  border-bottom: 1px solid var(--color-gray);\n  padding-bottom: 0.35rem;\n  margin-bottom: 0.75rem;\n}\n\n/* The chooser's own colour, so anything inside it that carries no class of its\n   own -- the empty-state line, the saved-filter list -- inherits something\n   legible instead of Bootstrap's near-black. */\n#pco-team-choices {\n  color: var(--color-white);\n}\n\n#pco-team-choices .pco-team-row + .pco-team-row {\n  margin-top: 0.3rem;\n}\n\n/* --color-gray (#616161) measured 3.39:1 against the panel, under the 4.5:1\n   AA floor. This is the head count beside each team, which is the whole reason\n   to look at the list. */\n#pco-team-choices .pco-team-meta {\n  color: rgba(255, 255, 255, 0.65);\n  font-size: 0.85em;\n}\n\n/* mic storage mode */\n.tvmode {\n  --tvmode-slot-width: 420px;\n  --tvmode-grid-gap: 6px;\n  --tvmode-base-height: 1080;\n  --tvmode-row-height: 100vh;\n  --tvmode-board-height: 100vh;\n  --tvmode-scale: 1;\n  --tvmode-scale-clamped: clamp(0.65, var(--tvmode-scale), 1.25);\n\n  #micboard,\n  .wirelessboard-board {\n    grid-template-columns: repeat(\n      auto-fit,\n      minmax(min(var(--tvmode-slot-width), 100%), var(--tvmode-slot-width))\n    );\n    grid-auto-rows: var(--tvmode-row-height);\n    justify-content: center;\n    align-content: flex-start;\n    grid-gap: var(--tvmode-grid-gap);\n    padding-left: var(--tvmode-grid-gap);\n    padding-right: var(--tvmode-grid-gap);\n    height: var(--tvmode-board-height, 100vh);\n  }\n\n  .col-sm {\n    background: var(--color-black);\n    width: min(var(--tvmode-slot-width), 100%);\n    max-width: var(--tvmode-slot-width);\n    height: var(--tvmode-row-height);\n    min-height: 0;\n  }\n\n  background-color: black;\n  min-height: 100vh;\n  overflow: hidden;\n\n  .blank {\n    background: black;\n  }\n\n  .above-mid {\n    height: 100%;\n  }\n\n  .name {\n    font-size: clamp(1.8rem, calc(var(--tvmode-row-height) * 0.085), 4rem);\n  }\n\n  .mic_id {\n    position: absolute;\n    top: 0;\n    font-size: clamp(1.4rem, calc(var(--tvmode-row-height) * 0.08), 3.4rem);\n    background: rgba(0, 0, 0, 0.6);\n    border-radius: 0.35rem;\n    padding: 0.25rem 0.45rem;\n  }\n\n  .mic_name {\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    align-items: center;\n    position: relative;\n    overflow: hidden;\n    padding: calc(1.4rem * var(--tvmode-scale-clamped)) 0.75rem calc(1rem * var(--tvmode-scale-clamped));\n    gap: calc(0.45rem * var(--tvmode-scale-clamped));\n    min-height: 0;\n  }\n\n  .mic_name .name {\n    width: 100%;\n    text-align: center;\n  }\n\n  .mic_name .mic_id {\n    align-self: flex-start;\n    margin-left: 0.5rem;\n  }\n\n  .mic_name > :not(.slot-media) {\n    position: relative;\n    z-index: 1;\n  }\n\n  .mic_name .slot-media {\n    position: absolute;\n    inset: 0;\n    display: none;\n    justify-content: center;\n    align-items: center;\n    pointer-events: none;\n    z-index: 0;\n  }\n\n  .mic_name .slot-media.is-active {\n    display: flex;\n  }\n\n  .mic_name .slot-media::after {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(180deg, rgba(0, 0, 0, 0.7) 0%, rgba(0, 0, 0, 0.45) 35%, rgba(0, 0, 0, 0.55) 100%);\n    opacity: 0;\n    transition: opacity 160ms ease-in-out;\n  }\n\n  .mic_name .slot-media.is-active::after {\n    opacity: 0.72;\n  }\n\n  .mic_name .slot-media img,\n  .mic_name .slot-media video {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n  }\n\n  .mic_name .name,\n  .mic_name .mic_id,\n  p.ext-name {\n    text-shadow: 0 2px 6px rgba(0, 0, 0, 0.65), 0 0 12px rgba(0, 0, 0, 0.55);\n  }\n\n  p.ext-name {\n    font-size: clamp(1.2rem, calc(var(--tvmode-row-height) * 0.06), 3rem);\n    color: var(--color-white);\n    opacity: 0.9;\n    margin: calc(0.3rem * var(--tvmode-scale-clamped)) 0.75rem calc(0.15rem * var(--tvmode-scale-clamped));\n    padding: 0 0.35rem;\n    background: rgba(0, 0, 0, 0.55);\n    border-radius: 0.4rem;\n    display: inline-block;\n    max-width: 100%;\n    text-align: center;\n    line-height: clamp(1.1, var(--tvmode-scale-clamped) * 1.2, 1.35);\n    white-space: normal;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n\n  .electrode {\n    bottom: calc(var(--tvmode-scale) * 250px);\n    height: calc(var(--tvmode-scale) * 125px);\n  }\n\n  .battery-bars {\n    bottom: calc(var(--tvmode-scale) * 225px);\n    height: calc(var(--tvmode-scale) * 25px);\n  }\n\n  canvas.slotgraph {\n    bottom: calc(var(--tvmode-scale) * 25px);\n    height: calc(var(--tvmode-scale) * 200px);\n  }\n\n  .offset {\n    bottom: calc(var(--tvmode-scale) * 180px);\n  }\n\n  .runtime {\n    bottom: calc(var(--tvmode-scale) * 180px);\n  }\n\n  .frequency,\n  .quality {\n    bottom: calc(var(--tvmode-scale) * 80px);\n  }\n\n  .errortype {\n    bottom: calc(var(--tvmode-scale) * 80px);\n  }\n\n  .ip {\n    bottom: calc(var(--tvmode-scale) * 60px);\n  }\n\n  .rxinfo {\n    bottom: calc(var(--tvmode-scale) * 40px);\n  }\n\n  .powerlock {\n    bottom: calc(var(--tvmode-scale) * 15px);\n    left: calc(var(--tvmode-scale) * 5px);\n  }\n\n  .diversity {\n    height: calc(var(--tvmode-scale) * 25px);\n  }\n\n  /* electrode & info drawer switch */\n  /* no electrode or info-drawer */\n  .elinfo00 .col-sm .mic_name {\n    height: 100%;\n  }\n\n  .elinfo00 .col-sm .electrode {\n    display: none;\n  }\n\n  .elinfo00 .col-sm .info-drawer {\n    display: none;\n  }\n\n  /* electrode */\n  .elinfo01 .col-sm .mic_name {\n    height: calc(100% - (var(--tvmode-scale) * 125px));\n    /* background-color: black; */\n    background: #262626;\n  }\n\n  .elinfo01 .col-sm .electrode {\n    display: block;\n    bottom: 0px;\n  }\n\n  .elinfo01 .col-sm .info-drawer {\n    display: none;\n  }\n\n\n  /* info drawer */\n  .elinfo10 .col-sm .mic_name {\n    height: calc(100% - (var(--tvmode-scale) * 250px));\n  }\n\n  .elinfo10 .col-sm .electrode {\n    display: none;\n  }\n\n  .elinfo10 .col-sm .info-drawer {\n    display: block;\n  }\n\n  /* electrode and info drawer */\n  .elinfo11 .col-sm .mic_name {\n    height: calc(100% - (var(--tvmode-scale) * 375px));\n    background: var(--color-black);\n  }\n\n  .elinfo11 .col-sm .electrode {\n    display: block;\n  }\n\n  .elinfo11 .col-sm info-drawer {\n    display: block;\n  }\n\n  .errortype{\n    position: absolute;\n    bottom: 80px;\n    right: 5px\n  }\n\n  .ip {\n    position: absolute;\n    bottom: 60px;\n    right: 5px;\n  }\n\n  .rxinfo {\n    position: absolute;\n    bottom: 40px;\n    right: 5px;\n  }\n\n  .navbar {\n    display: none;\n  }\n}\n\n/* browser mode */\n.deskmode {\n  .electrode {\n    display: none;\n  }\n  .info-drawer {\n    height: 130px;\n  }\n\n  .header {\n    display:none;\n\n  }\n